package com.example.backend.entity; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="messages") public class Message { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="conversation_id") private Conversation conversation; @ManyToOne(optional=false) @JoinColumn(name="sender_id") private User sender; @Column(nullable=false,columnDefinition="TEXT") private String content; private LocalDateTime readAt; @Column(nullable=false) private LocalDateTime createdAt; public Message(){} public Message(Conversation c,User s,String content){this.conversation=c;this.sender=s;this.content=content;} @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public Conversation getConversation(){return conversation;} public User getSender(){return sender;} public String getContent(){return content;} public LocalDateTime getReadAt(){return readAt;} public LocalDateTime getCreatedAt(){return createdAt;} public void markRead(){readAt=LocalDateTime.now();} }
